clean_output:
self.logger.debug("New reading: {}".format(sensor_value))
self._store_reading(sensor_value)

if self._last_reading is None:
    self._last_reading = sensor_value
else:
    if sensor_value < self._last_reading:
        self._last_reading = sensor_value
        self._low_reading_count +=

